"""Snap spans to a clock step, such as every 15 minutes."""

from typing import Iterable, List

from hourglass.models import Span
from hourglass.parsing import format_span

def _check_step(step_minutes: int) -> None:
    """A step must be positive and divide an hour evenly."""
    if step_minutes <= 0 or 60 % step_minutes:
        raise ValueError(f"bad step: {step_minutes}")

def _snap(minutes: int, step: int) -> int:
    """Nearest multiple of step. Exact halves round up."""
    return (minutes + step // 2) // step * step

def _round(span: Span, step: int) -> Span:
    start = _snap(span.start, step)
    stop = _snap(span.end, step)
    return Span(start, stop)

def _label(span: Span) -> str:
    hours, rest = divmod(span.minutes, 60)
    return f"{format_span(span)} ({hours}h {rest:02d}m)"

# ---
def rounded_labels(
    spans: Iterable[Span], step_minutes: int
) -> List[str]:
    """Snap each span to the step, then label it."""
    _check_step(step_minutes)
    snapped = [_round(span, step_minutes) for span in spans]
    return [_label(span) for span in snapped]

