import unittest

from hourglass.rounding import rounded_labels
from hourglass.models import Span

class RoundedLabelTests(unittest.TestCase):
    def test_rounds_to_nearest_step(self):
        labels = rounded_labels([Span(543, 1036)], 15)
        self.assertEqual(labels, ["09:00-17:15 (8h 15m)"])

    def test_exact_multiples_are_unchanged(self):
        labels = rounded_labels([Span(540, 1020)], 15)
        self.assertEqual(labels, ["09:00-17:00 (8h 00m)"])

    def test_exact_half_rounds_up(self):
        labels = rounded_labels([Span(545, 595)], 10)
        self.assertEqual(labels, ["09:10-10:00 (0h 50m)"])

    def test_end_of_day_stays_at_midnight(self):
        labels = rounded_labels([Span(1400, 1440)], 60)
        self.assertEqual(labels, ["23:00-24:00 (1h 00m)"])

    def test_one_label_per_span(self):
        spans = [Span(60, 125), Span(480, 487)]
        labels = rounded_labels(spans, 5)
        expected = [
            "01:00-02:05 (1h 05m)",
            "08:00-08:05 (0h 05m)"
        ]
        self.assertEqual(labels, expected)

    def test_empty_list(self):
        self.assertEqual(rounded_labels([], 15), [])

    def test_bad_steps_raise(self):
        for step in (0, -15, 7, 25, 45, 90):
            with self.subTest(step=step):
                with self.assertRaises(ValueError):
                    rounded_labels([Span(60, 120)], step)

    def test_hour_and_minute_steps_are_allowed(self):
        labels = rounded_labels([Span(61, 119)], 60)
        self.assertEqual(labels, ["01:00-02:00 (1h 00m)"])
        labels = rounded_labels([Span(61, 119)], 1)
        self.assertEqual(labels, ["01:01-01:59 (0h 58m)"])

    def test_span_that_collapses_raises(self):
        with self.assertRaises(ValueError):
            rounded_labels([Span(1, 4)], 15)
